#[local] Notation "'u'" := bv_unsigned (only parsing).

Definition PC_bilateralDestroy : Z := 240220.
Definition BD_WIN : Z := 2048.       (* [comment removed for export] *)

(* [comment removed for export] *)
Definition bil_blocks (bil : Z) (b : bilw) (q : word) : Prop :=
  In q (map (Z_to_bv 64) [bil; bw_nc b; bw_kx b; bw_kf b; bw_spat b; bw_rng b; bw_bsc b; bw_datas b; bw_pa b; bw_parr b; bw_ba b; bw_barr b; bw_ls b]) \/
  exists i, (0 <= i < 10)%Z /\ (q = Z_to_bv 64 (bw_pixes b i) \/ q = Z_to_bv 64 (bw_datad b i) \/ q = Z_to_bv 64 (bw_linesf b i)).

(* [comment removed for export] *)
Definition bilateralDestroy_contract : Prop :=
  forall C Ar A m md regs (s pp bil pixs w h datas : Z) (b : bilw) (ret : word) (S : TSet),
  Cok C -> W C A m md ->
  getr regs 2 = Z_to_bv 64 s -> (s mod 16 = 0)%Z -> (c_top C - LSTK + BD_WIN <= s)%Z -> (s <= pp)%Z -> (pp + 8 <= c_top C)%Z -> (pp mod 8 = 0)%Z ->
  getr regs 1 = ret -> ret_ok ret -> getr regs 4 = Z_to_bv 64 352880 -> getr regs 10 = Z_to_bv 64 pp ->
  rdn SEGS m (Z_to_bv 64 pp) 8 = Some (Z_to_le_bytes 8 bil) ->
  bil_obj C Ar A m bil pixs (hdv w h 8 0 datas) b -> (1 <= w)%Z -> (1 <= h)%Z ->
  live A (Z_to_bv 64 pixs) = Some 64%Z -> live (c_A0 C) (Z_to_bv 64 pixs) = None -> live Ar (Z_to_bv 64 pixs) = Some 64%Z ->
  (forall A' m' vm' regs', W C A' m' (with_vmmaps vm' md) -> cs_kept regs regs' ->
     (forall q : word, bil_blocks bil b q -> live A' q = None) -> (forall q : word, ~ bil_blocks bil b q -> live A' q = live A q) ->
     POSTMc C A' (pp + 8) (pixs + 20) 4 m m' -> (forall a : word, (s <= u a < pp)%Z -> m' a = m a) ->
     PIXat m' pixs (hdv w h 8 0 datas) -> rdn SEGS m' (Z_to_bv 64 pp) 8 = Some (Z_to_le_bytes 8 0) ->
     roomtr A (m_vmmaps md) A' vm' 0 0 ->
     realizes SEGS (mkCfg (mkst regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
  realizes SEGS (mkCfg (mkst regs (Z_to_bv 64 PC_bilateralDestroy) m al_rom) md) S.

(* [comment removed for export] *)
Lemma POSTM_of_POSTMc : forall C A (m m' : word -> option byte) md (s c : Z) (n : nat) (p : word) (np : Z) (bs : list byte),
  Cok C -> W C A m md -> POSTMc C A s c (Z.of_nat n) m m' -> live A p = Some np -> (u p <= c)%Z -> (c + Z.of_nat n <= u p + np)%Z -> length bs = n ->
  (forall i, (0 <= i < Z.of_nat n)%Z -> m' (Z_to_bv 64 (c + i)) <> None) ->
  rdn SEGS m (Z_to_bv 64 c) n = Some bs -> rdn SEGS m' (Z_to_bv 64 c) n = Some bs -> POSTM C A s m m'.
Proof.
